inputs = ['xcgewc', 'xcikcg', 'haiz', 'axj', 'fyzj']
outputs = ['icgewc', 'icikcg', 'yzuabiz', 'abij', 'yzuizj']

# Let's look at what's changing in each case
for i, (inp, outp) in enumerate(zip(inputs, outputs)):
    print(f"Example {i}: '{inp}' -> '{outp}'")
    # Find differences
    min_len = min(len(inp), len(outp))
    diff_pos = None
    for j in range(min_len):
        if inp[j] != outp[j]:
            diff_pos = j
            break

    if diff_pos is not None:
        print(f"  First difference at position {diff_pos}")
        print(f"  Input char: '{inp[diff_pos]}' -> Output char: '{outp[diff_pos]}'")
    else:
        if len(inp) != len(outp):
            print(f"  Length changed: {len(inp)} -> {len(outp)}")

    print()

